<script setup>
import { computed } from 'vue';
import { useMainStore } from '@/stores/main';

defineProps({
    variant: {
        type: String,
        required: true,
        validator: (value) => ['cloudflare-radar', 'mybooks-midnight', 'hacker-news-compact'].includes(value),
    },
