defineProps({
    variant: {
        type: String,
        required: true,
        validator: (value) => ['cobalt', 'slate', 'minimal'].includes(value),
    },
});

const store = useMainStore();
const footerText = computed(() => store.sys.footer || '');
const footerExtraHtml = computed(() => store.sys.footer_extra_html || '');
</script>

