    self.assertEqual(
        builtin_names,
        {"cobalt", "slate", "minimal"},
    )
    self.assertEqual(
        builtin_display_names,
        {
            "cobalt": "蓝色科技主题",
            "slate": "灰色紧凑主题",
            "minimal": "极简主题",
        },
    )

