1	import { describe, expect, it } from 'vitest';
2	import { builtinThemeLoaders, isBuiltinTheme, loadBuiltinThemeComponent } from '~/utils/builtin-themes';
3	
4	describe('builtin-themes', () => {
5	    it('recognizes only shipped builtin themes', () => {
6	        expect(isBuiltinTheme({ builtin: true, name: 'cobalt' })).toBe(true);
7	        expect(isBuiltinTheme({ builtin: true, name: 'slate' })).toBe(true);
8	        expect(isBuiltinTheme({ builtin: true, name: 'minimal' })).toBe(true);
9	        expect(isBuiltinTheme({ builtin: true, name: 'graphite' })).toBe(true);
10	        expect(isBuiltinTheme({ builtin: true, name: 'brass' })).toBe(true);
11	        expect(isBuiltinTheme({ builtin: true, name: 'card-catalog' })).toBe(true);
12	        expect(isBuiltinTheme({ builtin: false, name: 'cobalt' })).toBe(false);
13	        expect(isBuiltinTheme({ builtin: true, name: 'custom-theme' })).toBe(false);
14	        expect(isBuiltinTheme(null)).toBe(false);
15	    });
16	
17	    it('registers local component loaders for every builtin theme', async () => {
18	        for (const themeName of ['cobalt', 'slate', 'minimal', 'graphite', 'brass', 'card-catalog'] as const) {
